Let me create a complete example showing the before and after. I'll assume a React component since that's common for search inputs:

**Before (fires on every keystroke):**
```jsx
import { useState } from 'react';

export function SearchUsers() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);

  const handleSearch = async (value) => {
    setQuery(value);
    const response = await fetch(`/api/search?q=${value}`);
    const data = await response.json();
    setResults(data);
  };

  return (
    <input
      type="text"
      placeholder="Search..."
      onChange={(e) => handleSearch(e.target.value)}
    />
  );
}
```

**After (with debounce):**
```jsx
import { useState, useEffect, useRef } from 'react';

export function SearchUsers() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);
  const timeoutRef = useRef(null);

  const handleSearch = async (value) => {
    setQuery(value);

    // Clear previous timeout
    if (timeoutRef.current) clearTimeout(timeoutRef.current);

    // Set new timeout
    timeoutRef.current = setTimeout(async () => {
      if (value.trim()) {
        const response = await fetch(`/api/search?q=${value}`);
        const data = await response.json();
        setResults(data);
      }
    }, 300); // 300ms debounce delay
  };

  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  return (
    <input
      type="text"
      placeholder="Search..."
      onChange={(e) => handleSearch(e.target.value)}
      value={query}
    />
  );
}
```

**Or as a custom hook:**
```jsx
function useDebounce(callback, delay) {
  const timeoutRef = useRef(null);

  const debouncedCallback = (value) => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => callback(value), delay);
  };

  useEffect(() => {
    return () => clearTimeout(timeoutRef.current);
  }, []);

  return debouncedCallback;
}

// Usage:
export function SearchUsers() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);

  const performSearch = useDebounce(async (value) => {
    const response = await fetch(`/api/search?q=${value}`);
    const data = await response.json();
    setResults(data);
  }, 300);

  return (
    <input
      onChange={(e) => {
        setQuery(e.target.value);
        performSearch(e.target.value);
      }}
      value={query}
      placeholder="Search..."
    />
  );
}
```

The key difference: instead of calling the API immediately on every keystroke, the debounce delays the API call by 300ms, canceling and restarting the timer each time the user types. This reduces API calls significantly.
